using NUnit.Framework;using Rootborn.Game.StudentLife;
namespace Rootborn.Tests.EditMode.StudentLife{
public sealed class CareerHintDailyResetTests{
private static StudentLifeProgress Fixture(){var d=new StudentLifeProgress("slot","player",12,10).ToSaveData();d.CareerCandidates=new CareerCandidateProgressSaveData{SaveSlot="slot",PlayerId="player",TodayHintResultLines=new[]{"candidate.fixture:hint.fixture:Revealed"},Candidates=new[]{new CareerCandidateProgressSaveData.CandidateEntry{CandidateId="candidate.fixture",UnderstandingScore=3,HintIds=new[]{"hint.fixture"}}},AppliedSourceRequestIds=new[]{"earned-source"}};return StudentLifeProgress.FromSaveData(d,null,null,null);}
[Test]public void AdvancingDay_ClearsOnlyTodayHintLines(){var p=Fixture();Assert.That(p.TryEndDay(null,out _),Is.True);Assert.That(p.CareerCandidates.TodayHintResultLines,Has.Length.EqualTo(1));Assert.That(p.TryStartNextDay(),Is.True);Assert.That(p.CareerCandidates.TodayHintResultLines,Is.Empty);var saved=p.ToSaveData().CareerCandidates;Assert.That(saved.Candidates[0].UnderstandingScore,Is.EqualTo(3));Assert.That(saved.Candidates[0].HintIds,Is.EqualTo(new[]{"hint.fixture"}));Assert.That(saved.AppliedSourceRequestIds,Is.EqualTo(new[]{"earned-source"}));}
[Test]public void FailedDayAdvance_KeepsTodayHintsForCurrentResult(){var p=Fixture();Assert.That(p.TryStartNextDay(),Is.False);Assert.That(p.CareerCandidates.TodayHintResultLines,Has.Length.EqualTo(1));}
[Test]public void ResultReadyReload_PreservesHintsUntilRealDayAdvance(){var p=Fixture();p.TryEndDay(null,out _);var reloaded=StudentLifeProgress.FromSaveData(p.ToSaveData(),null,null,null);Assert.That(reloaded.CareerCandidates.TodayHintResultLines,Has.Length.EqualTo(1));Assert.That(reloaded.TryStartNextDay(),Is.True);Assert.That(reloaded.ToSaveData().CareerCandidates.TodayHintResultLines,Is.Empty);}
}}
